# Crop the real page captures into clippings (crops only, nothing altered) + highlight boxes (clip px). Writes _shared/clips.js
import json, os
from PIL import Image
D = os.path.abspath(os.path.join(os.path.dirname(__file__), '..')); S = os.path.join(D, '_src'); O = os.path.join(S, 'clips'); os.makedirs(O, exist_ok=True)
def clip(name, base, img, top, box, phrases=(), source='', date=''):
    j = json.load(open(os.path.join(S, base + '.json'))); im = Image.open(os.path.join(S, img)).convert('RGB')
    x0, y0, x1, y1 = box; im.crop(box).save(os.path.join(O, name + '.png'))
    if top == 'main': top = j['clipTop']
    hl = []
    for p in phrases:
        for r in j['found'].get(p, [])[:1] if p != '*' else []:
            hl.append([round(r[0] * 1.5 - x0), round((r[1] - top) * 1.5 - y0), round(r[2] * 1.5), round(r[3] * 1.5)])
    return name, {'w': x1 - x0, 'h': y1 - y0, 'hl': hl, 'source': source, 'date': date, 'url': j['url']}
out = dict([
  clip('ec-head', 'ec-sweep', 'ec-sweep.png', 'main', (100, 110, 1800, 430), ['148', '399'], 'European Commission, press release IP/23/418', '30 Jan 2023'),
  clip('ec-42', 'ec-sweep', 'ec-sweep.png', 'main', (560, 1128, 1530, 1390), ['42 websites'], 'European Commission, press release IP/23/418', '30 Jan 2023'),
  clip('ftc-76', 'ftc-sweep', 'ftc-sweep__nearly-76.png', 639.703125 if False else json.load(open(os.path.join(S, 'ftc-sweep.json')))['focus']['nearly 76']['top'], (330, 668, 1600, 880), ['642', 'nearly 76', 'nearly 67'], 'FTC press release', '10 Jul 2024'),
  clip('gdpr-32', 'gdpr-r32', 'gdpr-r32__silence-pre-ticked-boxes.png', json.load(open(os.path.join(S, 'gdpr-r32.json')))['focus']['Silence, pre-ticked boxes or inactivity']['top'], (790, 772, 1780, 852), ['Silence, pre-ticked boxes or inactivity'], 'GDPR Recital 32, gdpr-info.eu', ''),
  clip('dd-confirm', 'dd-types', 'dd-types__confirmshaming.png', json.load(open(os.path.join(S, 'dd-types.json')))['focus']['Confirmshaming']['top'], (184, 746, 946, 1062), [], 'deceptive.design/types', 'Harry Brignull'),
  clip('dd-urgency', 'dd-types', 'dd-types__confirmshaming.png', json.load(open(os.path.join(S, 'dd-types.json')))['focus']['Confirmshaming']['top'], (184, 58, 946, 374), [], 'deceptive.design/types', 'Harry Brignull'),
  clip('dd-scarcity', 'dd-types', 'dd-types__confirmshaming.png', 0, (184, 402, 946, 718), [], 'deceptive.design/types', 'Harry Brignull'),
  clip('dd-nagging', 'dd-types', 'dd-types__confirmshaming.png', 0, (976, 58, 1738, 374), [], 'deceptive.design/types', 'Harry Brignull'),
  clip('dd-origin', 'dd-about', 'dd-about__2010.png', json.load(open(os.path.join(S, 'dd-about.json')))['focus']['2010']['top'], (740, 1150, 1730, 1345), [], 'deceptive.design/about-us', ''),
])
# manual highlight for dd-origin: "started in 2010" line 1 and "Harry Brignull" (line 1 end + line 2 start) in clip px
out['dd-origin']['hl'] = [[443, 10, 207, 34], [822, 10, 75, 34], [0, 48, 118, 34]]
json.dump(out, open(os.path.join(O, 'clips.json'), 'w'), indent=1)
open(os.path.join(D, '_shared', 'clips.js'), 'w').write('/* generated by _tools/clips.py: real page clippings (crops only) + highlight boxes in clip px */\nconst CLIPS = ' + json.dumps(out) + ';\n')
for k, v in out.items(): print(k, v['w'], v['h'], v['hl'])
